var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic;
var scene=UnityEngine.Object.FindAnyObjectByType<Game.Composition.MatchSceneView>();
var boot=scene.GetType().GetProperty("MatchBootstrap",flags).GetValue(scene);
var ctx=boot.GetType().GetProperty("BuildingUiCommandContext",flags).GetValue(boot);
var callback=ctx.GetType().GetField("CanConfirmBuildingPlacement",flags).GetValue(ctx);
var harness=typeof(Game.Editor.SkirmishS002AriaRunHarness);
var find=harness.GetMethod("FindAirportPlacementSource",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);
var src=find.Invoke(null,new object[]{callback,new System.Collections.Generic.HashSet<object>(),0});
var defs=src.GetType().GetField("BuildingDefinitionPrefabSystemHelper",flags).GetValue(src);
var entries=(System.Collections.IEnumerable)defs.GetType().GetProperty("ConfiguredSpawnableDefinitions",flags).GetValue(defs);
foreach(var d in entries) {
var prefab=(UnityEngine.GameObject)d.GetType().GetField("Prefab",flags).GetValue(d);
if(prefab==null || prefab.name!="Building_Airport") continue;
return new { prefab=prefab.name, footprint=d.GetType().GetField("FootprintCells",flags).GetValue(d), bounds=d.GetType().GetField("LocalBounds",flags).GetValue(d), hasRunway=d.GetType().GetField("HasRunway",flags).GetValue(d), materials=d.GetType().GetField("MaterialsCost",flags).GetValue(d), physicalSourceModified=false };
} return "Airport definition missing";
